-- Moat's databases on PostgreSQL, first migration (DT-03, DT-13). Generated by `prisma migrate
-- diff` (without its `CREATE SCHEMA "public"`: the tables go into the connection's own schema),
-- then the CHECK constraints and triggers were written by hand (CLAUDE.md, Database): Prisma does
-- not model them. Keep them equal in meaning to ../../../sqlite/migrations. JSON fields are
-- compared with IS NOT DISTINCT FROM: a missing field must fail the CHECK, not pass it as NULL.

-- CreateTable
CREATE TABLE "history_entry" (
    "seq" INTEGER NOT NULL CHECK ("seq" >= 1),
    "at" TEXT NOT NULL CHECK ("at" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9]\.[0-9]{3}Z$'),
    "kind" TEXT NOT NULL CHECK ("kind" IN ('history_started', 'bundle_signed', 'secret_sealed', 'deploy', 'config_edited', 'database_pushed', 'database_pulled')),
    "details" TEXT NOT NULL CHECK (jsonb_typeof("details"::jsonb) IS NOT DISTINCT FROM 'object' AND length("details") <= 4096),
    "prev_hash" TEXT NOT NULL CHECK ("prev_hash" ~ '^[0-9a-f]{64}$'),
    "hash" TEXT NOT NULL CHECK ("hash" ~ '^[0-9a-f]{64}$'),

    CONSTRAINT "history_entry_pkey" PRIMARY KEY ("seq")
);

-- CreateTable
CREATE TABLE "sync_project" (
    "key" TEXT NOT NULL CHECK ("key" ~ '^[a-z][a-z0-9-]{0,62}$'),
    "config_text" TEXT NOT NULL CHECK (octet_length("config_text") <= 262144),
    "config_hash" TEXT NOT NULL CHECK ("config_hash" ~ '^[0-9a-f]{64}$'),
    "revision" INTEGER NOT NULL CHECK ("revision" >= 1),
    "updated_at" TEXT NOT NULL CHECK ("updated_at" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9]\.[0-9]{3}Z$'),

    CONSTRAINT "sync_project_pkey" PRIMARY KEY ("key")
);

-- CreateTable
CREATE TABLE "sync_gate" (
    "project" TEXT NOT NULL,
    "name" TEXT NOT NULL CHECK ("name" ~ '^[a-z][a-z0-9-]{0,62}$'),
    "text" TEXT NOT NULL CHECK (("text"::jsonb ->> 'moat') IS NOT DISTINCT FROM 'gate' AND jsonb_typeof("text"::jsonb -> 'gateId') IS NOT DISTINCT FROM 'string' AND jsonb_typeof("text"::jsonb -> 'boxKey') IS NOT DISTINCT FROM 'string' AND length("text") <= 4096),

    CONSTRAINT "sync_gate_pkey" PRIMARY KEY ("project","name")
);

-- CreateTable
-- Ciphertext only (SEC-31): the text must be a sealed secret of this version, nothing else.
CREATE TABLE "sync_secret" (
    "project" TEXT NOT NULL,
    "gate" TEXT NOT NULL CHECK ("gate" ~ '^[a-z][a-z0-9-]{0,62}$'),
    "name" TEXT NOT NULL CHECK ("name" ~ '^[a-z][a-z0-9-]{0,62}$'),
    "secret_version" INTEGER NOT NULL CHECK ("secret_version" >= 1),
    "text" TEXT NOT NULL CHECK (("text"::jsonb ->> 'alg') IS NOT DISTINCT FROM 'x25519-blake2b-xchacha20poly1305' AND ("text"::jsonb -> 'secretVersion') IS NOT DISTINCT FROM to_jsonb("secret_version") AND jsonb_typeof("text"::jsonb -> 'epk') IS NOT DISTINCT FROM 'string' AND jsonb_typeof("text"::jsonb -> 'nonce') IS NOT DISTINCT FROM 'string' AND jsonb_typeof("text"::jsonb -> 'ct') IS NOT DISTINCT FROM 'string' AND length("text") <= 65536),

    CONSTRAINT "sync_secret_pkey" PRIMARY KEY ("project","gate","name")
);

-- CreateTable
CREATE TABLE "sync_bundle" (
    "project" TEXT NOT NULL,
    "gate" TEXT NOT NULL CHECK ("gate" ~ '^[a-z][a-z0-9-]{0,62}$'),
    "version" INTEGER NOT NULL CHECK ("version" BETWEEN 1 AND 999999999),
    "digest" TEXT NOT NULL CHECK ("digest" ~ '^[0-9a-f]{64}$'),
    "text" TEXT NOT NULL CHECK (("text"::jsonb ->> 'moat') IS NOT DISTINCT FROM 'bundle' AND jsonb_typeof("text"::jsonb -> 'payload') IS NOT DISTINCT FROM 'string' AND octet_length("text") <= 1048576),

    CONSTRAINT "sync_bundle_pkey" PRIMARY KEY ("project","gate","version")
);

-- CreateIndex
CREATE UNIQUE INDEX "history_entry_hash_key" ON "history_entry"("hash");

-- AddForeignKey
ALTER TABLE "sync_gate" ADD CONSTRAINT "sync_gate_project_fkey" FOREIGN KEY ("project") REFERENCES "sync_project"("key") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "sync_secret" ADD CONSTRAINT "sync_secret_project_fkey" FOREIGN KEY ("project") REFERENCES "sync_project"("key") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "sync_bundle" ADD CONSTRAINT "sync_bundle_project_fkey" FOREIGN KEY ("project") REFERENCES "sync_project"("key") ON DELETE CASCADE ON UPDATE CASCADE;

-- The history is append-only, and a signed bundle is never replaced (DT-13): its key is the lock,
-- a new version is a new row.
CREATE FUNCTION "moat_refuse_change"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% rows are never changed', TG_TABLE_NAME;
END
$$;

CREATE TRIGGER "history_entry_append_only" BEFORE UPDATE OR DELETE ON "history_entry"
    FOR EACH ROW EXECUTE FUNCTION "moat_refuse_change"();

CREATE TRIGGER "sync_bundle_no_update" BEFORE UPDATE ON "sync_bundle"
    FOR EACH ROW EXECUTE FUNCTION "moat_refuse_change"();
